-- Tripin starter destination import; generated from the reviewed JSON seed.
-- Partial coverage only: 120 candidates from Bali, DKI Jakarta, Kalimantan Timur, and Sumatera Utara.
-- Required source attribution: Data by Audiala — https://audiala.com (CC BY 4.0).
-- Entity/coordinate pages: Wikidata (CC0). Photos use linked Wikidata P18 files and store
-- Commons author, source page, license, and license URL per row.
-- Unknown description, ticket price, hours, address, or unavailable photos remain NULL.
-- NULL ticket_price means unknown; 0 remains reserved for a confirmed free destination.
-- Inserts are guarded against existing slug/name+province records; no rows are deleted.
-- Existing non-empty image_url values are preserved.
BEGIN;
ALTER TABLE public.destinations
  ADD COLUMN IF NOT EXISTS image_credit text,
  ADD COLUMN IF NOT EXISTS image_source_url text,
  ADD COLUMN IF NOT EXISTS image_license text,
  ADD COLUMN IF NOT EXISTS image_license_url text,
  ADD COLUMN IF NOT EXISTS data_source text,
  ADD COLUMN IF NOT EXISTS data_source_url text,
  ADD COLUMN IF NOT EXISTS data_source_license text;
-- The existing table marks ticket_price NOT NULL, but this sourced dataset has no verified prices.
-- Allow NULL rather than inventing a price or incorrectly marking an attraction as free.
ALTER TABLE public.destinations
  ALTER COLUMN ticket_price DROP NOT NULL;
CREATE TEMP TABLE tripin_destination_seed (
  id uuid,name text,slug text,province text,city text,description text,image_url text,
  ticket_price numeric,latitude double precision,longitude double precision,opening_hours text,
  address text,is_published boolean,image_credit text,image_source_url text,image_license text,
  image_license_url text,data_source text,data_source_url text,data_source_license text,categories text[]
) ON COMMIT DROP;
UPDATE public.destinations d
SET image_url=s.image_url,image_credit=s.image_credit,image_source_url=s.image_source_url,
    image_license=s.image_license,image_license_url=s.image_license_url
FROM tripin_destination_seed s
WHERE d.image_url IS NULL AND s.image_url IS NOT NULL
  AND lower(trim(d.name))=lower(trim(s.name))
  AND lower(trim(coalesce(d.province,'')))=lower(trim(coalesce(s.province,'')));
  id,name,slug,province,city,description,image_url,ticket_price,latitude,longitude,opening_hours,address,
  is_published,image_credit,image_source_url,image_license,image_license_url,data_source,data_source_url,
  data_source_license,created_at,updated_at
)
SELECT s.id,s.name,s.slug,s.province,s.city,s.description,s.image_url,s.ticket_price,s.latitude,s.longitude,
       s.opening_hours,s.address,s.is_published,s.image_credit,s.image_source_url,s.image_license,
       s.image_license_url,s.data_source,s.data_source_url,s.data_source_license,now(),now()
FROM tripin_destination_seed s
WHERE NOT EXISTS (
  SELECT 1 FROM public.destinations d
  WHERE lower(trim(d.slug))=lower(trim(s.slug))
     OR (lower(trim(d.name))=lower(trim(s.name))
         AND lower(trim(coalesce(d.province,'')))=lower(trim(coalesce(s.province,''))))
)
ON CONFLICT DO NOTHING;
SELECT d.id,c.id
FROM tripin_destination_seed s
JOIN public.destinations d ON lower(trim(d.slug))=lower(trim(s.slug))
  OR (lower(trim(d.name))=lower(trim(s.name))
      AND lower(trim(coalesce(d.province,'')))=lower(trim(coalesce(s.province,''))))
CROSS JOIN LATERAL unnest(s.categories) AS source_category(name)
JOIN public.destination_categories c
  ON lower(c.name)=lower(source_category.name)
  OR lower(c.slug)=lower(replace(source_category.name,' ','-'))
  OR lower(c.name)=CASE source_category.name WHEN 'Nature' THEN 'alam' WHEN 'Culture' THEN 'budaya'
       WHEN 'History' THEN 'sejarah' WHEN 'Family' THEN 'keluarga' ELSE lower(source_category.name) END
  OR lower(c.slug)=CASE source_category.name WHEN 'Nature' THEN 'alam' WHEN 'Culture' THEN 'budaya'
       WHEN 'History' THEN 'sejarah' WHEN 'Family' THEN 'keluarga' ELSE lower(replace(source_category.name,' ','-')) END
WHERE NOT EXISTS (
  SELECT 1 FROM public.destination_category_relations x
  WHERE x.destination_id=d.id AND x.category_id=c.id
)
ON CONFLICT DO NOTHING;
CREATE TEMP TABLE tripin_photo_seed (
  slug text,name text,province text,image_url text,image_credit text,image_source_url text,
  image_license text,image_license_url text
) ON COMMIT DROP;
UPDATE public.destinations d
SET image_url=p.image_url,image_credit=p.image_credit,image_source_url=p.image_source_url,
    image_license=p.image_license,image_license_url=p.image_license_url
FROM tripin_photo_seed p
WHERE d.image_url IS NULL
  AND (lower(trim(d.slug))=lower(trim(p.slug))
       OR (lower(trim(d.name))=lower(trim(p.name))
           AND lower(trim(coalesce(d.province,'')))=lower(trim(coalesce(p.province,'')))));
COMMIT;
